<?php require 'app_core.php';$token=$_GET['token']??$_POST['token']??'';$hash=hash('sha256',$token);$st=db()->prepare('SELECT pr.*,u.name,u.email FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>NOW() LIMIT 1');$st->execute([$hash]);$r=$st->fetch();$err='';$ok=false;if($_SERVER['REQUEST_METHOD']==='POST'&&$r){$pw=$_POST['password']??'';$pw2=$_POST['password2']??'';if(strlen($pw)<10)$err='La contraseña debe tener al menos 10 caracteres.';elseif($pw!==$pw2)$err='Las contraseñas no coinciden.';else{db()->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$r['user_id']]);db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$r['id']]);send_app_mail($r['email'],'Contraseña modificada','<p>Su contraseña del Planificador Gantt DRALA fue modificada correctamente.</p><p>Si usted no realizó este cambio, contacte al administrador.</p>');$ok=true;}}?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="assets/style.css?v=5.0"><title>Nueva contraseña</title></head><body class="login"><div class="login-card"><h1>Nueva contraseña</h1><?php if($ok):?><div class="ok">Contraseña modificada correctamente.</div><a class="login-button" style="display:block;text-align:center" href="login.php">Ingresar</a><?php elseif(!$r):?><div class="bad">El enlace es inválido, ya fue utilizado o venció.</div><a href="forgot_password.php">Solicitar otro enlace</a><?php else:?><?php if($err):?><div class="bad"><?=h($err)?></div><?php endif;?><form method="post"><input type="hidden" name="token" value="<?=h($token)?>"><label>Nueva contraseña<input type="password" name="password" required minlength="10"></label><label>Repetir contraseña<input type="password" name="password2" required minlength="10"></label><button class="login-button">Guardar nueva contraseña</button></form><?php endif;?></div></body></html>
